-- PT116-S3-Q5. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT116-S3-Q5$batch09$ AND q.stimulus=$batch09$Art critic: The aesthetic value of a work of art lies in its ability to impart a stimulating character to the audience’s experience of the work.$batch09$ AND q.prompt=$batch09$Which one of the following judgments most closely conforms with the principle cited above?$batch09$ AND q.correct_choice=$batch09$E$batch09$) THEN RAISE EXCEPTION 'Question changed: PT116-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT116-S3-Q5$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S3-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT116-S3-Q5$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$A work of art's aesthetic value lies in its ability to make the audience's experience stimulating.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The rule ties value to one thing: the effect on the audience. A judgment conforms if it praises or faults a work because of how it affects its audience. A judgment that rests on the artist, the material, or originality uses some other standard.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A judgment of a work's value based on its effect on the audience.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT116-S3-Q5$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Being a copy is about originality. An exact copy could still give an audience a stimulating experience.$batch09$), ($batch09$B$batch09$, $batch09$The symphony doesn't excite the audience, yet it's called beautiful because it's performed competently. By the critic's standard, failing to stimulate is the problem.$batch09$), ($batch09$C$batch09$, $batch09$The cube is praised for a rare material. That says nothing about the audience's experience.$batch09$), ($batch09$D$batch09$, $batch09$This is the trap, picked by 6%. A controversial artist might seem stimulating. But D praises the painting for who painted it, not for what it does to the people looking at it.$batch09$), ($batch09$E$batch09$, $batch09$The poem is called deficient because it has little impact on its audience. Little impact means no stimulating experience. That's exactly what the critic's principle uses to judge value.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT116-S3-Q5$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
